import { useEffect, useState } from "react";
import { BrowserRouter, Navigate, Route, Routes, useNavigate, useParams } from "react-router";

type Draft = { name: string; email: string };
const emptyDraft: Draft = { name: "", email: "" };

function loadDraft(): Draft {
  if (typeof window === "undefined") return emptyDraft;
  try {
    const saved: unknown = JSON.parse(sessionStorage.getItem("application-draft") ?? "null");
    if (typeof saved !== "object" || saved === null) return emptyDraft;
    const fields = saved as Record<string, unknown>;
    if (typeof fields.name !== "string" || typeof fields.email !== "string") return emptyDraft;
    return { name: fields.name, email: fields.email };
  } catch { return emptyDraft; }
}

function Wizard({ draft, setDraft }: { draft: Draft; setDraft: (value: Draft) => void }) {
  const { step } = useParams<{ step: string }>();
  const navigate = useNavigate();
  if (step === "profile") return (
    <section>
      <input value={draft.name} onChange={(e) => setDraft({ ...draft, name: e.target.value })} />
      <button disabled={!draft.name.trim()} onClick={() => navigate("/apply/contact")}>Next</button>
    </section>
  );
  if (step === "contact") return (
    <section>
      <input type="email" value={draft.email} onChange={(e) => setDraft({ ...draft, email: e.target.value })} />
      <button onClick={() => navigate("/apply/profile")}>Back</button>
      <button disabled={!draft.email.includes("@")}>Submit</button>
    </section>
  );
  return <Navigate to="/apply/profile" replace />;
}

export default function App() {
  const [draft, setDraft] = useState<Draft>(loadDraft);
  useEffect(() => {
    try { sessionStorage.setItem("application-draft", JSON.stringify(draft)); }
    catch { /* Recovery is best-effort when storage is unavailable. */ }
  }, [draft]);
  return (
    <BrowserRouter><Routes>
      <Route path="apply/:step" element={<Wizard draft={draft} setDraft={setDraft} />} />
      <Route path="*" element={<Navigate to="/apply/profile" replace />} />
    </Routes></BrowserRouter>
  );
}
