import { useEffect, useState } from "react";
import { BrowserRouter, Link, Route, Routes, useParams } from "react-router";

const projects: Record<string, string> = { atlas: "Atlas", beacon: "Beacon" };
type LoadState = { kind: "loading" } | { kind: "ready"; name: string } | { kind: "missing" };

function ProjectPage() {
  const { projectId } = useParams<{ projectId: string }>();
  const [state, setState] = useState<LoadState>({ kind: "loading" });

  useEffect(() => {
    const controller = new AbortController();
    setState({ kind: "loading" });
    const timer = window.setTimeout(() => {
      if (controller.signal.aborted) return;
      const name = projectId ? projects[projectId] : undefined;
      setState(name ? { kind: "ready", name } : { kind: "missing" });
    }, 200);
    return () => { controller.abort(); window.clearTimeout(timer); };
  }, [projectId]);

  if (state.kind === "loading") return <p>Loading project…</p>;
  if (state.kind === "missing") return <p>Project not found. <Link to="/projects">View projects</Link></p>;
  return <h1>{state.name}</h1>;
}

export default function App() {
  return (
    <BrowserRouter><Routes>
      <Route path="projects" element={<Link to="/projects/atlas">Open Atlas</Link>} />
      <Route path="projects/:projectId" element={<ProjectPage />} />
      <Route path="*" element={<h1>Page not found</h1>} />
    </Routes></BrowserRouter>
  );
}
